<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Struk {{ $transaction->order_number }}</title><style>body{font-family:monospace;margin:0;color:#111}.receipt{width:72mm;margin:auto;padding:4mm}h1,p{margin:0}.center{text-align:center}.line{border-top:1px dashed #111;margin:10px 0}.row{display:flex;justify-content:space-between;gap:8px;margin:5px 0}.bold{font-weight:bold}@media print{.actions{display:none}@page{size:80mm auto;margin:0}}</style></head><body><div class="receipt"><div class="center"><h1>ANGKRINGAN S1</h1><p>Struk Pembayaran</p></div><div class="line"></div><p>{{ $transaction->order_number }}</p><p>{{ $transaction->created_at->format('d/m/Y H:i') }}</p><p>{{ $transaction->customer_name }}</p><div class="line"></div>@foreach($transaction->items as $item)<p class="bold">{{ $item->menu_name }}</p><div class="row"><span>{{ $item->quantity }} x {{ number_format($item->price, 0, ',', '.') }}</span><span>{{ number_format($item->subtotal, 0, ',', '.') }}</span></div>@endforeach<div class="line"></div><div class="row bold"><span>TOTAL</span><span>Rp {{ number_format($transaction->total, 0, ',', '.') }}</span></div><p>Bayar: {{ strtoupper($transaction->payment_label) }}</p><div class="line"></div><p class="center">Terima kasih</p><div class="actions center" style="margin-top:20px"><button onclick="printReceipt()">Cetak</button> <a href="{{ route('admin.orders.show', $transaction) }}">Kembali</a></div></div><script>async function printReceipt(){window.print();await fetch(@json(route('admin.orders.printed', $transaction)),{method:'POST',headers:{'X-CSRF-TOKEN':@json(csrf_token()),'Accept':'application/json'}})}@if(request()->boolean('auto')) window.addEventListener('load',printReceipt); @endif</script></body></html>
